plans={phase:read(phase+'-fanout.json') for phase in ['before','after']}
paths=sorted({f for rows in plans.values() for r in rows for f in r['object_outputs']});ids={p:i for i,p in enumerate(paths)}
compact={phase:[{**{k:v for k,v in r.items() if k!='object_outputs'},'object_ids':[ids[f] for f in r['object_outputs']]} for r in rows] for phase,rows in plans.items()}
changes=[]
for after in plans['after']:
 before=next(r for r in plans['before'] if all(r[k]==after[k] for k in ['compiler','header','target']))
 changes.append({**{k:after[k] for k in ['compiler','header','target']},'removed_object_ids':[ids[f] for f in before['object_outputs'] if f not in after['object_outputs']],'added_object_ids':[ids[f] for f in after['object_outputs'] if f not in before['object_outputs']]})
samples=[r for phase in ['before','after'] for r in read(phase+'-timings.json')];assert len(samples)==4
for r in samples:
 expected=next(p['object_outputs'] for p in plans[r['phase']] if p['compiler']==r['compiler'] and p['header'].endswith('/backend.hpp') and p['target']=='hex_demo')
 assert set(expected)==set(r['object_outputs'])
syntax={};attempts=[]
for file in sorted(out.glob('syntax-results-*.json'),key=lambda p:('targeted' in p.name,p.name)):
 for r in read(file.name):syntax[r['configuration'],r['source']]=r;attempts.append(r)
