 db=json.loads((base/dirname/'compile_commands.json').read_text());entries=[e for e in db if 'kin_renderer_headers_check.dir' in e['output']];assert len(entries)==11;contracts[compiler]=[]
 for e in entries:
  args=shlex.split(e['command']);assert '-include' not in args and '-include-pch' not in args and 'Unity/' not in e['file'];contracts[compiler].append({'source':str(pathlib.Path(e['file']).resolve().relative_to(repo)),'command':e['command']})
 e=next(e for e in db if e['file'].endswith('/engine/src/renderer/render_queue.cpp'));args=shlex.split(e['command']);assert '-O1' not in args and [a for a in args if a.startswith('-O')][-1]=='-O2';commands[compiler]=e['command']
validation=read('validation-results.json');restore=read('restore-results.json');assert len(validation)==len(restore)==2
for compiler in ['clang','gcc']:assert 'out of 25' in (out/(compiler+'-tests.log')).read_text()
