mechanical=read('mechanical-check.json');hashes={}
for name in mechanical['existing_cpp_files_checked']:
 hashes[name]={'before':hashlib.sha256(subprocess.check_output(['git','show',mechanical['base_commit']+':'+name],cwd=repo)).hexdigest(),'after':hashlib.sha256((repo/name).read_bytes()).hexdigest()}
